resource "google_storage_bucket" "secure_bucket" {
  name     = var.bucket_name
  project  = var.project_id
  location = var.location

  # Enforce uniform bucket-level access (disables object-level ACLs)
  uniform_bucket_level_access = true

  # Prevent all public access to the bucket and its objects
  public_access_prevention = "enforced"

  # Optional safety defaults
  force_destroy = false
}

output "bucket_name" {
  description = "The name of the created storage bucket."
  value       = google_storage_bucket.secure_bucket.name
}

