resource "google_storage_bucket" "secure_bucket" {
  name                        = "org-standard-secure-bucket"
  location                    = "asia-south1"
  storage_class               = "STANDARD"
  uniform_bucket_level_access = true

  # Note: The retrieved context does not explicitly document the
  # 'public_access_prevention' attribute for google_storage_bucket, but
  # setting it to "enforced" satisfies the requirement to prevent public access.
  public_access_prevention = "enforced"

  # Organizational policy requires storage resources to declare an explicit
  # retention policy or protection if not explicitly temporary/scratch.
  # Note: 'retention_policy' is used here to enforce 30-day retention (in seconds).
  retention_policy {
    retention_period = 2592000
  }

  versioning {
    enabled = true
  }

  labels = {
    environment = "prod"
  }
}

