# Terraform configuration for a highly available (regional) MySQL 8.0 Cloud SQL instance

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

