  region = "us-central1"
}

resource "random_id" "db_name_suffix" {
  byte_length = 4
}

resource "google_sql_database_instance" "mysql_ha" {
  name             = "mysql8-ha-instance-${random_id.db_name_suffix.hex}"
  database_version = "MYSQL_8_0"
  region           = "us-central1"

  # Set to true for production workloads to prevent accidental instance deletion
  deletion_protection = false

  settings {
    tier = "db-custom-2-7680"

    # Enables high availability (regional deployment across multiple zones)
    availability_type = "REGIONAL"

    backup_configuration {
      enabled            = true
      binary_log_enabled = true # Required for point-in-time recovery and read replicas in MySQL
      start_time         = "03:00"
      transaction_log_retention_days = 7
      backup_retention_settings {
        retained_backups = 7
        retention_unit   = "COUNT"
      }
    }

    ip_configuration {
      ipv4_enabled = true
    }
  }
}

