# Terraform configuration for a regional GKE cluster in asia-south1
# with default node pool removed and a dedicated node pool.

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

