  region = "asia-south1"
}

# ------------------------------------------------------------------------------
# VPC NETWORK AND SUBNETWORK
# ------------------------------------------------------------------------------

resource "google_compute_network" "vpc" {
  name                    = "gke-vpc"
  auto_create_subnetworks = false
}

resource "google_compute_subnetwork" "subnet" {
  name                     = "gke-subnet-asia-south1"
  region                   = "asia-south1"
  network                  = google_compute_network.vpc.id
  ip_cidr_range            = "10.10.0.0/20"
  private_ip_google_access = true

  secondary_ip_range {
    range_name    = "gke-pods"
    ip_cidr_range = "10.20.0.0/16"
  }

  secondary_ip_range {
    range_name    = "gke-services"
    ip_cidr_range = "10.30.0.0/20"
  }
}

# ------------------------------------------------------------------------------
# SERVICE ACCOUNT FOR GKE NODES
# ------------------------------------------------------------------------------

resource "google_service_account" "gke_nodes" {
  account_id   = "gke-node-pool-sa"
  display_name = "GKE Node Pool Service Account"
}

resource "google_project_iam_member" "node_service_account_roles" {
  for_each = toset([
    "roles/logging.logWriter",
    "roles/monitoring.metricWriter",
    "roles/monitoring.viewer",
    "roles/artifactregistry.reader"
  ])

  project = google_service_account.gke_nodes.project
  role    = each.key
  member  = "serviceAccount:${google_service_account.gke_nodes.email}"
}

# ------------------------------------------------------------------------------
# REGIONAL GKE CLUSTER
# ------------------------------------------------------------------------------

resource "google_container_cluster" "primary" {
  name     = "regional-gke-asia-south1"
  location = "asia-south1"

  # Remove the default node pool to use a separately managed node pool
  remove_default_node_pool = true
  initial_node_count       = 1

  network    = google_compute_network.vpc.id
  subnetwork = google_compute_subnetwork.subnet.id

  ip_allocation_policy {
    cluster_secondary_range_name  = google_compute_subnetwork.subnet.secondary_ip_range[0].range_name
    services_secondary_range_name = google_compute_subnetwork.subnet.secondary_ip_range[1].range_name
  }

  deletion_protection = false
}

# ------------------------------------------------------------------------------
# SEPARATELY MANAGED GKE NODE POOL
# ------------------------------------------------------------------------------

resource "google_container_node_pool" "primary_nodes" {
  name     = "primary-node-pool"
  location = google_container_cluster.primary.location
  cluster  = google_container_cluster.primary.name

  # In a regional cluster spanning 3 zones (asia-south1-a, asia-south1-b, asia-south1-c),
  # setting node_count to 1 creates 1 node per zone, totaling 3 nodes across the cluster.
  node_count = 1

  node_config {
    machine_type = "e2-standard-4"

    service_account = google_service_account.gke_nodes.email
    oauth_scopes = [
      "https://www.googleapis.com/auth/cloud-platform"
    ]

    metadata = {
      disable-legacy-endpoints = "true"
    }
  }

  management {
    auto_repair  = true
    auto_upgrade = true
  }
}

